import{_ as t}from"./chunks/home.KfBfMT0S.js";import{_ as a,a as i,b as r,c as n,d as o,e as s}from"./chunks/languages.BS_4zFMB.js";import{_ as l}from"./chunks/kefu-chat.CQaKJK-O.js";import{_ as d,o as p,c,a2 as g}from"./chunks/framework.DDY-poMm.js";const T=JSON.parse('{"title":"Mobile App","description":"","frontmatter":{},"headers":[],"relativePath":"app/overview.md","filePath":"app/overview.md","lastUpdated":1790683574000}'),h={name:"app/overview.md"};function m(u,e,f,b,x,v){return p(),c("div",null,[...e[0]||(e[0]=[g('<h1 id="mobile-app" tabindex="-1">Mobile App <a class="header-anchor" href="#mobile-app" aria-label="Permalink to &quot;Mobile App&quot;">​</a></h1><p>RWABTX is the platform&#39;s <strong>native dual-platform app (Android / iOS)</strong>.</p><p>We <strong>did not take the &quot;web wrapper&quot; approach</strong>. Built with Flutter, everything from login, markets, charts, ordering and settlement to assets, deposits and withdrawals has been rewritten as native screens. Compared with a wrapper, this brings three clear differences: <strong>faster startup, responsive interaction, and eligibility for official app stores</strong>.</p><p>The app shares the same backend and account system as the web — <strong>one account, identical data on web and app, switch between them at any time</strong>.</p><h2 id="screens" tabindex="-1">Screens <a class="header-anchor" href="#screens" aria-label="Permalink to &quot;Screens&quot;">​</a></h2><div style="display:flex;flex-wrap:wrap;gap:28px 20px;justify-content:center;margin:32px 0;"><figure style="margin:0;flex:0 0 220px;max-width:220px;"><img src="'+t+'" alt="App home page" style="border-radius:10px;border:1px solid var(--vp-c-divider);"><figcaption style="text-align:center;font-size:13px;color:var(--vp-c-text-2);margin-top:10px;line-height:1.5;"><b>Home</b><br>Asset overview and shortcuts; the grid is configured in the admin console </figcaption></figure><figure style="margin:0;flex:0 0 220px;max-width:220px;"><img src="'+a+'" alt="Candlestick chart" style="border-radius:10px;border:1px solid var(--vp-c-divider);"><figcaption style="text-align:center;font-size:13px;color:var(--vp-c-text-2);margin-top:10px;line-height:1.5;"><b>Charts</b><br>Professional TradingView charts with multiple timeframes and indicators </figcaption></figure><figure style="margin:0;flex:0 0 220px;max-width:220px;"><img src="'+i+'" alt="Seconds contracts" style="border-radius:10px;border:1px solid var(--vp-c-divider);"><figcaption style="text-align:center;font-size:13px;color:var(--vp-c-text-2);margin-top:10px;line-height:1.5;"><b>Seconds contracts</b><br>Periods and settlement parameters are configured by the platform in the admin console </figcaption></figure><figure style="margin:0;flex:0 0 220px;max-width:220px;"><img src="'+r+'" alt="TradFi instruments" style="border-radius:10px;border:1px solid var(--vp-c-divider);"><figcaption style="text-align:center;font-size:13px;color:var(--vp-c-text-2);margin-top:10px;line-height:1.5;"><b>TradFi</b><br>Forex and other traditional instruments; clearly marked and not tradable while markets are closed </figcaption></figure><figure style="margin:0;flex:0 0 220px;max-width:220px;"><img src="'+n+'" alt="Asset overview" style="border-radius:10px;border:1px solid var(--vp-c-divider);"><figcaption style="text-align:center;font-size:13px;color:var(--vp-c-text-2);margin-top:10px;line-height:1.5;"><b>Assets</b><br>Separate platform / wealth / contract accounts, with holdings at a glance </figcaption></figure><figure style="margin:0;flex:0 0 220px;max-width:220px;"><img src="'+o+'" alt="Deposit" style="border-radius:10px;border:1px solid var(--vp-c-divider);"><figcaption style="text-align:center;font-size:13px;color:var(--vp-c-text-2);margin-top:10px;line-height:1.5;"><b>Deposit</b><br>Network labeled per coin, with a direct warning that deposits on the wrong chain cannot be recovered </figcaption></figure><figure style="margin:0;flex:0 0 220px;max-width:220px;"><img src="'+s+'" alt="Languages" style="border-radius:10px;border:1px solid var(--vp-c-divider);"><figcaption style="text-align:center;font-size:13px;color:var(--vp-c-text-2);margin-top:10px;line-height:1.5;"><b>Languages</b><br>7 built-in languages; availability controlled in the admin console </figcaption></figure><figure style="margin:0;flex:0 0 220px;max-width:220px;"><img src="'+l+'" alt="Live chat" style="border-radius:10px;border:1px solid var(--vp-c-divider);"><figcaption style="text-align:center;font-size:13px;color:var(--vp-c-text-2);margin-top:10px;line-height:1.5;"><b>Live chat</b><br>Chat directly in the app; agents reply from Telegram, text and images in real time </figcaption></figure></div><div class="tip custom-block"><p class="custom-block-title">About these screenshots</p><p>All are <strong>real-device captures</strong> of the signed Android release build, not mockups, taken with the app in Simplified Chinese (English and 5 other languages are built in). Balances, prices and product parameters are <strong>demo environment data</strong> and do not represent an actual operating configuration — all of these are set by the platform in its own admin console.</p></div><h2 id="trading" tabindex="-1">Trading <a class="header-anchor" href="#trading" aria-label="Permalink to &quot;Trading&quot;">​</a></h2><ul><li><strong>Markets and charts</strong>: professional TradingView charts with multiple timeframes and a full set of indicators; prices are pushed in real time</li><li><strong>Seconds contracts</strong>: order → countdown → automatic settlement, all native. The countdown is based solely on the server&#39;s fixing time, so what you see is the real settlement moment</li><li><strong>USDT-margined perpetuals</strong>: a complete loop of transfer, open, hold and close — market/limit orders, 10-level order book and real-time P&amp;L on one screen</li><li><strong>Spot and instant swap</strong>: both trading methods side by side</li><li><strong>TradFi</strong>: forex, commodities, stocks, indices and other traditional instruments, with the same trading experience as digital assets</li></ul><h2 id="assets-and-funds" tabindex="-1">Assets and funds <a class="header-anchor" href="#assets-and-funds" aria-label="Permalink to &quot;Assets and funds&quot;">​</a></h2><p>Asset overview, account breakdown (spot / contract / wealth accounts at a glance), transfers, deposits, withdrawals, deposit/withdrawal history and ledger — all native.</p><p>The deposit page correctly labels TRC20 / ERC20 / BEP20 and other networks per coin, preventing wrong-chain deposits at the source.</p><h2 id="wealth-products" tabindex="-1">Wealth products <a class="header-anchor" href="#wealth-products" aria-label="Permalink to &quot;Wealth products&quot;">​</a></h2><p>Wealth management (three sections), staking, assisted lending and mining are all native screens. Token subscription (IPO) — project list, subscribing, orders and status changes — is fully native. Copy trading and lead trading are supported too.</p><h2 id="account-and-security" tabindex="-1">Account and security <a class="header-anchor" href="#account-and-security" aria-label="Permalink to &quot;Account and security&quot;">​</a></h2><ul><li><strong>Sign-up / login / password recovery</strong>: the app has full standalone registration, with no jump to the web</li><li>KYC, email verification, bank cards, terms, VIP tiers and <a href="/CoinExchange/guide/customer-service">live chat</a> are all native</li><li>HTTPS + HTTP/2 at the network layer; expired sessions are detected immediately and redirected safely</li></ul><h2 id="operator-configurable" tabindex="-1">Operator-configurable <a class="header-anchor" href="#operator-configurable" aria-label="Permalink to &quot;Operator-configurable&quot;">​</a></h2><p>The platform&#39;s admin console controls how the app looks, <strong>with no new release needed</strong>:</p><ul><li>Bottom navigation tabs, home service grid, &quot;Me&quot; menu and asset page tabs are all driven by admin configuration</li><li>Announcements, help center, download center, white paper and referral center content are maintained in the admin console</li><li><strong>Referral deep-link attribution</strong>: when users install the app from a referral link, the referral relationship is carried over automatically, so the agent/referral system continues fully in the app</li></ul><h2 id="languages" tabindex="-1">Languages <a class="header-anchor" href="#languages" aria-label="Permalink to &quot;Languages&quot;">​</a></h2><p><strong>7 built-in languages</strong>: Simplified Chinese, Traditional Chinese, English, Japanese, Korean, Vietnamese and Thai. The language list is controlled in the admin console and can be switched on or off per operating region.</p><h2 id="automatic-updates" tabindex="-1">Automatic updates <a class="header-anchor" href="#automatic-updates" aria-label="Permalink to &quot;Automatic updates&quot;">​</a></h2><p>The app automatically detects new versions and prompts users to update; the download and installation can be completed inside the app. See <a href="/CoinExchange/app/install">Install &amp; Update</a>.</p><hr><div class="tip custom-block"><p class="custom-block-title">iOS</p><p>Android and iOS share the same native codebase. <strong>The iOS version is published after being signed with your Apple developer certificate.</strong></p></div>',25)])])}const A=d(h,[["render",m]]);export{T as __pageData,A as default};
